/// Reproducible identity for the vendored library. The commit identifies the upstream
/// base; the version suffix identifies DockShell's documented font-resize patch.
public enum SwiftTermBuildInfo {
    public static let branch: String? = nil
    public static let tag: String? = nil
    public static let commit: String? = "464df5207fc2432e16c9a23abe538187196daf5f"
    public static let hasUncommittedChanges: Bool? = nil
    public static let version = "1.19.0+dockshell.1"
}
